import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`personal-cash-flow`,heroTitle:`Optimize your cash flow in minutes`,heroSubtitle:`Perplexity Computer builds your budget, models scenarios, and picks investments — personalized to your situation and goals.`,inputUrlCta:`Build my plan`,inputUrlPlaceholder:`e.g. $120k salary, $2k rent, $30k savings...`,inputUrlPrefill:`Ask me about my financial situation — income, expenses, debts, savings, and goals. Then build a detailed monthly budget and 10-year investment plan. Model at least 3 scenarios (conservative, moderate, aggressive) and optimize across all of them. Deliver: 1) A monthly cash flow budget with category breakdowns. 2) A debt payoff schedule if applicable. 3) A 10-year projected returns model for each scenario. 4) Specific stock and ETF recommendations with allocation percentages. 5) A summary comparing all scenarios with a recommended path.`,heroOverlaySteps:[`Analyzing your income, expenses, debts, and savings goals`,`Loading current market data and investment research tools`,`Modeling conservative, moderate, and aggressive scenarios over 10 years`,`Stock picks, allocation percentages, and projected returns — ready to invest`],generatingSteps:[`Parsing your financial details to map income, expenses, and net cash flow`,`Designing an agent to model 10-year return scenarios across risk profiles`,`Configuring stock screening and portfolio allocation engines for each scenario`,`Setting up budget templates, projection charts, and investment recommendations`],featureSectionTitle:`From paycheck to portfolio`,featureCardTitles:[`Connects to your finance stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Yahoo Finance, Mint, YNAB — Computer plugs into your tools so budgets, projections, and trades live where you already work.`,`Monthly budgets with category breakdowns. 10-year projection models. Scenario comparisons. Specific stock and ETF picks with allocation percentages. Debt payoff schedules.`],capabilitySectionTitle:`Your financial advisor, on autopilot`,capabilitySectionSubtitle:`Describe your situation, step away, get a complete investment plan.`,capabilityCards:[{title:`Budget Optimization`,description:`Computer can analyze your income and expenses — fixed costs, discretionary spending, debt obligations — and build a monthly budget that maximizes savings rate.`},{title:`Scenario Modeling`,description:`Computer can run conservative, moderate, and aggressive projections over 10 years — comparing compound returns, risk exposure, and drawdown probabilities.`},{title:`Stock Selection`,description:`Computer can screen equities and ETFs based on your risk profile, time horizon, and goals — and recommend specific tickers with allocation percentages.`},{title:`Connect Your Tools`,description:`Computer reads your live portfolio through Plaid and delivers the analysis in Excel — your data, your tools, your format.`},{title:`Remember & Learn`,description:`Computer can remember your income changes, spending patterns, and risk tolerance across sessions — so every plan builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch market conditions and your portfolio drift — set up a monitoring workflow that pings you when rebalancing is needed.`}]});export{t as default};
